begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated,service_role;
select no_plan();
-- Synthetic source records and references, never a production legal approval.
-- This fixture proves restriction effects; it does not publish a campaign or send email.
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('a2520000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','restriction252-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)select('a2520000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'COMPLIANCE_MANAGER'from generate_series(1,2)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2520000-0000-4000-8000-000000000001','TEST restrictions252','TEST restrictions252','ACTIVE','a2520000-0000-4000-8000-000000000003'),('b2520000-0000-4000-8000-000000000002','TEST foreign252','TEST foreign252','ACTIVE','a2520000-0000-4000-8000-000000000004');
insert into public.organization_memberships(id,organization_id,user_id,status)values('c2520000-0000-4000-8000-000000000001','b2520000-0000-4000-8000-000000000001','a2520000-0000-4000-8000-000000000003','ACTIVE');
insert into public.organization_member_roles(membership_id,role_code)values('c2520000-0000-4000-8000-000000000001','CLIENT_OWNER');
insert into public.data_subject_requests(id,organization_id,request_type,subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,correlation_id,created_by)select('d2520000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'b2520000-0000-4000-8000-000000000001',case when i=4 then'ERASURE'else'RESTRICTION'end,encode(extensions.digest(convert_to('b2520000-0000-4000-8000-000000000001:a2520000-0000-4000-8000-000000000003','UTF8'),'sha256'),'hex'),'ENHANCED','fr-MA','IN_REVIEW',now()+interval'1 day',now(),extensions.gen_random_uuid(),'a2520000-0000-4000-8000-000000000001'from generate_series(1,4)i;
create temporary table r252(k text primary key,v jsonb);grant all on r252 to authenticated,service_role;
create function pg_temp.actor252(p_i integer,p_aal text default'aal2')returns void language plpgsql as $$declare uid text:='a2520000-0000-4000-8000-'||lpad(p_i::text,12,'0');begin perform set_config('request.jwt.claim.sub',uid,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','aal',p_aal)::text,true);end$$;
create function pg_temp.service252()returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"service_role"}',true);end$$;
insert into public.marketing_consents(organization_id,purpose,decision,policy_version,evidence_hash,decided_by)values('b2520000-0000-4000-8000-000000000001','MARKETING_ANALYTICS','GRANTED','TEST_252',repeat('a',64),'a2520000-0000-4000-8000-000000000003');
insert into public.brand_kits(id,organization_id,status,created_by)values('e2520000-0000-4000-8000-000000000030','b2520000-0000-4000-8000-000000000001','DRAFT','a2520000-0000-4000-8000-000000000003');
insert into public.brand_kit_versions(id,brand_kit_id,version,payload,content_hash,change_reason,created_by)values('e2520000-0000-4000-8000-000000000031','e2520000-0000-4000-8000-000000000030',1,'{"legal_name":"A","trade_name":"A","primary_colors":[],"tone":"PRO","languages":["FR"],"primary_cta":"GO","tracked_url":"https://example.invalid","required_mentions":[],"forbidden_terms":[],"approved_hashtags":[]}',repeat('e',64),'TEST_252 test','a2520000-0000-4000-8000-000000000003');
update public.brand_kits set status='READY',current_version_id='e2520000-0000-4000-8000-000000000031'where id='e2520000-0000-4000-8000-000000000030';
insert into public.marketing_templates(id,template_key,status,created_by)values('e2520000-0000-4000-8000-000000000040','PROBLEM_SOLUTION','DRAFT','a2520000-0000-4000-8000-000000000001')on conflict(template_key)do nothing;
insert into public.marketing_template_versions(id,template_id,version,structure,frequency_max_weekly,content_hash,created_by)values('e2520000-0000-4000-8000-000000000041',(select id from public.marketing_templates where template_key='PROBLEM_SOLUTION'),(select coalesce(max(version),0)+1 from public.marketing_template_versions where template_id=(select id from public.marketing_templates where template_key='PROBLEM_SOLUTION')),'{"hook":"h","body":"b","target_characters":100,"required_media":[],"allowed_ctas":[],"forbidden_claims":[],"translation_rules":{},"repetition_rules":{}}',8,repeat('f',64),'a2520000-0000-4000-8000-000000000001');
update public.marketing_templates set status='ACTIVE',current_version_id='e2520000-0000-4000-8000-000000000041'where id='e2520000-0000-4000-8000-000000000040';
insert into public.marketing_campaigns(id,organization_id,brand_kit_version_id,mode,title_fr,title_ar,status,frequency_max_weekly,risk_threshold,audience_snapshot,source_snapshot,approved_by,approved_at,created_by)values('e2520000-0000-4000-8000-000000000050','b2520000-0000-4000-8000-000000000001','e2520000-0000-4000-8000-000000000031','ASSISTED','Campagne TEST_252','حملة','APPROVED',8,20,'{}','{}','a2520000-0000-4000-8000-000000000003',now(),'a2520000-0000-4000-8000-000000000003');
insert into public.marketing_content(id,campaign_id,channel,template_version_id)values
('e2520000-0000-4000-8000-000000000060','e2520000-0000-4000-8000-000000000050','INSTAGRAM','e2520000-0000-4000-8000-000000000041'),
('e2520000-0000-4000-8000-000000000061','e2520000-0000-4000-8000-000000000050','FACEBOOK','e2520000-0000-4000-8000-000000000041'),
('e2520000-0000-4000-8000-000000000062','e2520000-0000-4000-8000-000000000050','REEL','e2520000-0000-4000-8000-000000000041');
set local role service_role;select pg_temp.service252();
insert into r252 values('touch',public.register_verified_marketing_touch_v2('a2520000-0000-4000-8000-000000000003','b2520000-0000-4000-8000-000000000001','e2520000-0000-4000-8000-000000000050','e2520000-0000-4000-8000-000000000060','linkedin','social',repeat('a',64),clock_timestamp()+interval'29 days'));
insert into r252 values('baseline-conversion',public.record_marketing_business_conversion_v2('REGISTRATION_STARTED','b2520000-0000-4000-8000-000000000001',(select(v->>'touch_id')::uuid from r252 where k='touch'),'TEST-252-baseline-conversion'));
reset role;
select is((select v->>'outcome'from r252 where k='baseline-conversion'),'MARKETING_BUSINESS_ATTRIBUTED','the actual source is attributable before a restriction');
select ok(private.dsr_restriction_consumer_proof_v1('MARKETING')->>'ready'='true','the four real installed consumer guards attest readiness');
select is(private.dsr_restriction_consumer_proof_v1('OPTIONAL_AI'),null::jsonb,'no nonexistent optional AI consumer is attested');
set local role authenticated;select pg_temp.actor252(1);
select throws_ok($$select public.transition_data_subject_request('d2520000-0000-4000-8000-000000000001',1,'FULFILLED','TEST_FREE_REFERENCE','TEST_FREE_REFERENCE',extensions.gen_random_uuid())$$,'55000','PRIVACY_RESTRICTION_EXECUTION_AND_DELIVERY_PROOF_REQUIRED','a free reference cannot falsely fulfil a restriction request');
select throws_ok($$select public.transition_data_subject_request('d2520000-0000-4000-8000-000000000004',1,'FULFILLED','TEST_FREE_REFERENCE','TEST_FREE_REFERENCE',extensions.gen_random_uuid())$$,'55000','PRIVACY_FULL_ERASURE_EVIDENCE_REQUIRED','full erasure remains closed without coverage and retention evidence');
select pg_temp.actor252(3,'aal1');
select throws_ok($$select public.confirm_my_processing_restriction_scope_v1('d2520000-0000-4000-8000-000000000001','APPLY',array['MARKETING'],'TEST-252-AAL1')$$,'42501','DSR_VERIFIED_SUBJECT_REQUIRED','scope confirmation needs the verified subject AAL2 session');
select pg_temp.actor252(4);
select throws_ok($$select public.confirm_my_processing_restriction_scope_v1('d2520000-0000-4000-8000-000000000001','APPLY',array['MARKETING'],'TEST-252-foreign-subject')$$,'42501','DSR_VERIFIED_SUBJECT_REQUIRED','another subject cannot choose this personal scope');
select pg_temp.actor252(3);
insert into r252 values('scope',public.confirm_my_processing_restriction_scope_v1('d2520000-0000-4000-8000-000000000001','APPLY',array['MARKETING'],'TEST-252-scope'));
insert into r252 values('ai-scope',public.confirm_my_processing_restriction_scope_v1('d2520000-0000-4000-8000-000000000003','APPLY',array['OPTIONAL_AI'],'TEST-252-ai-scope'));
select pg_temp.actor252(1);
select throws_ok($$select public.propose_dsr_processing_restriction_v1('d2520000-0000-4000-8000-000000000001',null,(select(v->>'scope_version_id')::uuid from r252 where k='scope'),'TEST-252-LAW-REFERENCE','TEST explicit subject scope restriction','TEST-252-null-CAS')$$,'40001','STALE_DSR_RESTRICTION_SCOPE','NULL CAS cannot bypass the verified request version');
insert into r252 values('proposal',public.propose_dsr_processing_restriction_v1('d2520000-0000-4000-8000-000000000001',1,(select(v->>'scope_version_id')::uuid from r252 where k='scope'),'TEST-252-LAW-REFERENCE','TEST synthetic restriction limited to this subject and organization','TEST-252-proposal'));
insert into r252 values('ai-proposal',public.propose_dsr_processing_restriction_v1('d2520000-0000-4000-8000-000000000003',1,(select(v->>'scope_version_id')::uuid from r252 where k='ai-scope'),'TEST-252-LAW-REFERENCE','TEST optional AI remains unsupported rather than falsely executed','TEST-252-ai-proposal'));
select throws_ok($$select public.review_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='proposal'),(select v->>'content_hash'from r252 where k='proposal'),true,true,'TEST-252-REVIEW-REFERENCE','TEST self review must be refused')$$,'42501','DSR_RESTRICTION_INDEPENDENT_REVIEW_REQUIRED','a preparer cannot approve their own restriction');
select pg_temp.actor252(2);
insert into r252 values('review',public.review_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='proposal'),(select v->>'content_hash'from r252 where k='proposal'),true,true,'TEST-252-REVIEW-REFERENCE','TEST independent review of scope and preserved legal business processing'));
insert into r252 values('ai-review',public.review_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='ai-proposal'),(select v->>'content_hash'from r252 where k='ai-proposal'),true,true,'TEST-252-REVIEW-REFERENCE','TEST approval does not manufacture an AI consumer'));
reset role;
select is(private.dsr_processing_is_restricted_v1('b2520000-0000-4000-8000-000000000001','a2520000-0000-4000-8000-000000000003','MARKETING'),false,'approval alone never applies the restriction');
set local role authenticated;
select throws_ok($$select public.apply_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='ai-proposal'),(select v->>'content_hash'from r252 where k='ai-proposal'),(select v->>'review_proof_hash'from r252 where k='ai-review'),'TEST-252-ai-apply')$$,'55000','DSR_RESTRICTION_SCOPE_NOT_IMPLEMENTED','unsupported AI scope cannot become an applied effect');
reset role;
insert into r252 values('consumer-dependency-ddl',jsonb_build_object('ddl',pg_get_functiondef('private.locked_marketing_processing_allowed_v1(uuid,uuid)'::regprocedure)));
create or replace function private.locked_marketing_processing_allowed_v1(p_organization_id uuid,p_subject_user_id uuid)returns boolean language plpgsql volatile security definer set search_path=pg_catalog,private as $$begin return false;end$$;
set local role authenticated;
select throws_ok($$select public.apply_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='proposal'),(select v->>'content_hash'from r252 where k='proposal'),(select v->>'review_proof_hash'from r252 where k='review'),'TEST-252-unattested-apply')$$,'55000','DSR_RESTRICTION_CONSUMER_GUARDS_REQUIRED','drifted consumer evidence cannot authorize an effect claim');
reset role;
do $$begin execute(select v->>'ddl'from r252 where k='consumer-dependency-ddl');end$$;
set local role authenticated;
insert into r252 values('application',public.apply_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='proposal'),(select v->>'content_hash'from r252 where k='proposal'),(select v->>'review_proof_hash'from r252 where k='review'),'TEST-252-apply'));
insert into r252 values('application-replay',public.apply_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='proposal'),(select v->>'content_hash'from r252 where k='proposal'),(select v->>'review_proof_hash'from r252 where k='review'),'TEST-252-apply-other-key'));
reset role;
select is((select v->>'application_id'from r252 where k='application'),(select v->>'application_id'from r252 where k='application-replay'),'another key cannot apply one approved proposal twice');
select ok(private.dsr_processing_is_restricted_v1('b2520000-0000-4000-8000-000000000001','a2520000-0000-4000-8000-000000000003','MARKETING'),'the real consumer helper observes the applied subject restriction');
select is(private.dsr_processing_is_restricted_v1('b2520000-0000-4000-8000-000000000002','a2520000-0000-4000-8000-000000000003','MARKETING'),false,'the effect does not spread to another organization');
select is(private.dsr_processing_is_restricted_v1('b2520000-0000-4000-8000-000000000001','a2520000-0000-4000-8000-000000000004','MARKETING'),false,'the effect does not spread to another subject');
set local role service_role;select pg_temp.service252();
insert into r252 values('blocked-touch',public.register_verified_marketing_touch_v2('a2520000-0000-4000-8000-000000000003','b2520000-0000-4000-8000-000000000001','e2520000-0000-4000-8000-000000000050','e2520000-0000-4000-8000-000000000060','linkedin','social',repeat('b',64),clock_timestamp()+interval'29 days'));
insert into r252 values('blocked-conversion',public.record_marketing_business_conversion_v2('REGISTRATION_STARTED','b2520000-0000-4000-8000-000000000001',(select(v->>'touch_id')::uuid from r252 where k='touch'),'TEST-252-restricted-conversion'));
reset role;
select is((select v->>'outcome'from r252 where k='blocked-touch'),'MARKETING_BUSINESS_SKIPPED_RESTRICTION','future personal touches are stopped before collection');
select is((select v->>'outcome'from r252 where k='blocked-conversion'),'MARKETING_BUSINESS_SKIPPED_RESTRICTION','reconciliation of an old source also respects the current restriction');
select is((select count(*)from public.marketing_attribution_events where organization_id='b2520000-0000-4000-8000-000000000001'),1::bigint,'the historical attributed record is preserved and no new attribution is invented');
set local role authenticated;select pg_temp.actor252(3);
insert into r252 values('intake',public.save_public_diagnostic_intake('b2520000-0000-4000-8000-000000000001','{"goals":["secure_activity"],"sector":"commerce","team_size":"small","priority_tracking":"regular","sales_tracking":"shared","backup_restore":"recent","decision_trace":"systematic","next_action":"Review source controls"}','fr',repeat('c',64)));
reset role;
select ok(exists(select 1 from public.public_diagnostic_intakes where id=(select(v->>'intake_id')::uuid from r252 where k='intake')),'the underlying legitimate business command still succeeds');
select ok(not exists(select 1 from private.marketing_business_facts_v2 where source_id=(select(v->>'intake_id')::uuid from r252 where k='intake')),'the source trigger no longer captures a personal marketing fact');
select is(private.ensure_marketing_business_fact_v2('DIAGNOSTIC_STARTED',(select(v->>'intake_id')::uuid from r252 where k='intake')),null::uuid,'the alternate reconciliation creator also refuses to create the restricted marketing fact');
set local role authenticated;select pg_temp.actor252(4);
select throws_ok($$select public.get_private_dsr_restriction_proof_v1((select(v->>'application_id')::uuid from r252 where k='application'))$$,'42501','DSR_PRIVATE_RESTRICTION_PROOF_DENIED','a foreign subject cannot open the private application proof');
select pg_temp.actor252(3);
select throws_ok($$select public.acknowledge_my_dsr_restriction_v1((select(v->>'application_id')::uuid from r252 where k='application'),(select(v->>'scope_version_id')::uuid from r252 where k='scope'),(select v->>'sha256'from r252 where k='application'))$$,'55000','DSR_RESTRICTION_PROOF_ACCESS_REQUIRED','an acknowledgement cannot replace actual access to the proof');
insert into r252 values('proof',public.get_private_dsr_restriction_proof_v1((select(v->>'application_id')::uuid from r252 where k='application')));
select throws_ok($$select public.acknowledge_my_dsr_restriction_v1((select(v->>'application_id')::uuid from r252 where k='application'),(select(v->>'scope_version_id')::uuid from r252 where k='scope'),repeat('f',64))$$,'40001','STALE_DSR_RESTRICTION_PROOF','a receipt must bind the exact proof bytes');
insert into r252 values('ack',public.acknowledge_my_dsr_restriction_v1((select(v->>'application_id')::uuid from r252 where k='application'),(select(v->>'scope_version_id')::uuid from r252 where k='scope'),(select v->>'sha256'from r252 where k='application')));
select pg_temp.actor252(1);
select lives_ok($$select public.transition_data_subject_request('d2520000-0000-4000-8000-000000000001',1,'FULFILLED','TEST_EFFECT_AND_DELIVERY',(select v->>'reference'from r252 where k='application'),extensions.gen_random_uuid())$$,'only an actual current effect with verified delivery can fulfil the restriction');
reset role;
select is((select status from public.data_subject_requests where id='d2520000-0000-4000-8000-000000000001'),'FULFILLED','the request reaches its factual fulfilled state after effect and receipt');
select ok((select(v->>'document_json')not like'%a2520000-0000-4000-8000-000000000001%'from r252 where k='proof'),'the subject proof does not expose another staff user identifier');
-- A later LIFT is a new verified subject request and a new independent review.
set local role authenticated;select pg_temp.actor252(3);
insert into r252 values('lift-scope',public.confirm_my_processing_restriction_scope_v1('d2520000-0000-4000-8000-000000000002','LIFT',array['MARKETING'],'TEST-252-lift-scope'));
select pg_temp.actor252(1);
insert into r252 values('lift-proposal',public.propose_dsr_processing_restriction_v1('d2520000-0000-4000-8000-000000000002',1,(select(v->>'scope_version_id')::uuid from r252 where k='lift-scope'),'TEST-252-LIFT-REFERENCE','TEST authenticated subject requested this exact scoped lifting','TEST-252-lift-proposal'));
select pg_temp.actor252(2);
insert into r252 values('lift-review',public.review_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='lift-proposal'),(select v->>'content_hash'from r252 where k='lift-proposal'),true,true,'TEST-252-LIFT-REVIEW','TEST independent review of lifting with prior history preserved'));
insert into r252 values('lift',public.apply_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='lift-proposal'),(select v->>'content_hash'from r252 where k='lift-proposal'),(select v->>'review_proof_hash'from r252 where k='lift-review'),'TEST-252-lift-apply'));
insert into r252 values('old-replay-after-lift',public.apply_dsr_processing_restriction_v1((select(v->>'proposal_id')::uuid from r252 where k='proposal'),(select v->>'content_hash'from r252 where k='proposal'),(select v->>'review_proof_hash'from r252 where k='review'),'TEST-252-old-proposal-replay'));
reset role;
select is(private.dsr_processing_is_restricted_v1('b2520000-0000-4000-8000-000000000001','a2520000-0000-4000-8000-000000000003','MARKETING'),false,'the newly reviewed lifting is the effective scoped action');
select is((select(v->>'current')::boolean from r252 where k='old-replay-after-lift'),false,'replaying an old APPLY returns its historical receipt without reactivating it');
select is((select count(*)from public.dsr_processing_restriction_applications_v1 where organization_id='b2520000-0000-4000-8000-000000000001'),2::bigint,'APPLY and LIFT each have one immutable execution, independent of retry keys');
select is((select count(*)from public.event_outbox where event_type='DsrRestrictionAppliedV1'and organization_id='b2520000-0000-4000-8000-000000000001'),2::bigint,'the two real effect facts are emitted once each');
set local role service_role;select pg_temp.service252();
insert into r252 values('after-lift-touch',public.register_verified_marketing_touch_v2('a2520000-0000-4000-8000-000000000003','b2520000-0000-4000-8000-000000000001','e2520000-0000-4000-8000-000000000050','e2520000-0000-4000-8000-000000000060','linkedin','social',repeat('d',64),clock_timestamp()+interval'29 days'));
reset role;
select is((select v->>'outcome'from r252 where k='after-lift-touch'),'MARKETING_TOUCH_CAPTURED','future marketing resumes only after the actual independently reviewed lifting');
select*from finish();rollback;
